@@ -508,9 +508,6 @@ static void *parse_key_value(struct parser *parser)
     size_t key_size;

     while (lexeme_buffer_consume(&parser->buffer, &lexeme)) {
-        if (lexeme->value.len == 0)
-            continue;
-
         lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
                                lexeme->value.len);

